import{z as o,x as i,o as t,c as d,q as l,j as B,D as r,d as e,s,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"学习索引","description":"","frontmatter":{"title":"学习索引","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/learned-index.md","filePath":"cs/learned-index.md","lastUpdated":1791413859000}'),p={name:"cs/learned-index.md"};function D(m,a,F,C,u,T){const n=i("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="学习索引" tabindex="-1">学习索引 <a class="header-anchor" href="#学习索引" aria-label="Permalink to &quot;学习索引&quot;">​</a></h1><div class="epigraph"><p>把有序键到位置看成回归：模型预测页号，再局部纠正。分布稳定时少一层指针，分布一漂就变成错页扫描。</p><footer>—— 据 Kraska et al., The Case for Learned Index Structures, SIGMOD 2018；B+ 对照</footer></div><p><a href="/cs/spatial-index-db">上一课</a>的键没有全序友好。本课回到一维有序键。缺口是：B+ 用内部节点存分隔键；若键分布可用函数逼近，模型可预测叶位置，内部节点缩小或消失。学习索引（learned index）是存储结构上的模型，与学习型优化器（选计划）不是同一插件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态有序数组上，CDF 模型预测 rank，误差界限内二分纠正。动态插入：要增量训练或混合结构（RMI + 缓冲树）。缺口是<strong>工作负载假设</strong>：只读或追加、键分布缓变。OLTP 随机插入、删除空洞，模型过期则预测偏差大，最坏退化成大范围扫描——比 B+ 最坏对数更差。</p><p>与 ART/Bw：那些是精确结构。学习索引用近似+纠正。事务、并发、恢复都要定义「模型版本」与页一致性。</p><p><span class="marginnote">Kraska et al. SIGMOD 2018。后续有动态学习索引。本课不把神经网络当 B+ 的默认替换。无虚构编号。</span></p><p><span class="marginnote">直觉类比：B+ 树像进图书馆每层都问导航台「下一层往哪走」；学习索引像把全馆布局背下来——「编号 37 万的书大约在第 4 排第 3 架」，一步到位，找错了几架就在旁边挪几步。代价是：一旦馆里大规模搬书（键分布漂移），背下的地图就系统性指错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：用键与位置拟合分段线性或小网络。查询：预测 → 在误差半径内搜。更新：缓冲新键，定期重训练，或把学习索引当只读段（LSM 里对 SST 建模型，不可变正好）。</p><p>优化器：代价按预测误差半径的期望探测次数，需校准。</p>',11)),(t(),B(A,null,{default:r(()=>[s(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E6%9C%89%E5%BA%8F%E9%94%AE%22%5D%20--%3E%20MOD%5B%22CDF%20%2F%20%E5%88%86%E6%AE%B5%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20MOD%20--%3E%20POS%5B%22%E9%A2%84%E6%B5%8B%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20POS%20--%3E%20FIX%5B%22%E8%AF%AF%E5%B7%AE%E5%8D%8A%E5%BE%84%E5%86%85%E7%BA%A0%E6%AD%A3%22%5D%0A%20%20UPD%5B%22%E6%8F%92%E5%85%A5%22%5D%20--%3E%20RET%5B%22%E7%BC%93%E5%86%B2%E6%88%96%E9%87%8D%E8%AE%AD%E7%BB%83%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"LSM+学习：对每个不可变 SST 训一个小模型，compaction 后重训，避开动态问题。B+ 内部页减少缓存占用，是论文卖点；要对比 ART 的前缀压缩是否已经够。",-1)),a[5]||(a[5]=E("p",null,"正确性：纠正步骤必须找到真键或证明不存在，不能只信模型。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：10 亿键、每页 100 键。B+ 树高约 4 层，每层可能一次缓存未命中（约 100 ns），点查约 400 ns；CDF 模型预测只是一次乘加（几纳秒），误差半径 10 个键内的二分只要三四次比较——「少一层指针」省的就是内部节点那几次内存访问。")],-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},[e("常见误区：初学者担心「模型预测错了会返回错的键」。不会：纠正步骤只在真实数据上收尾，找到真键或证明不存在，正确性不靠模型。模型错误的代价是"),E("strong",null,"性能"),e("——误差半径变大，局部搜索涨成大范围扫描，最坏退化为线性，连 B+ 的对数界都保不住。")])],-1)),(t(),B(A,null,{default:r(()=>[s(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%9F%A5%E8%AF%A2%E9%94%AE%20x%22%5D%20--%3E%20CDF%5B%22%E7%B4%AF%E7%A7%AF%E5%88%86%E5%B8%83%20CDF(x)%3A%20%E9%94%AE%20%E2%89%A4%20x%20%E7%9A%84%E5%8D%A0%E6%AF%94%22%5D%0A%20%20CDF%20--%3E%20RANK%5B%22%E5%8D%A0%E6%AF%94%20%C3%97%20%E9%94%AE%E6%80%BB%E6%95%B0%20%E2%89%88%20x%20%E7%9A%84%E6%8E%92%E5%90%8D%22%5D%0A%20%20RANK%20--%3E%20PG%5B%22%E6%8E%92%E5%90%8D%20%C3%B7%20%E6%AF%8F%E9%A1%B5%E9%94%AE%E6%95%B0%20%3D%20%E9%A2%84%E6%B5%8B%E9%A1%B5%E5%8F%B7%22%5D%0A%20%20PG%20--%3E%20FIX%5B%22%E5%9C%A8%E8%AF%AF%E5%B7%AE%E5%8D%8A%E5%BE%84%E5%86%85%E5%B1%80%E9%83%A8%E6%90%9C%E7%B4%A2%E6%94%B6%E5%B0%BE%22%5D%0A%20%20DRIFT%5B%22%E5%88%86%E5%B8%83%E6%BC%82%E7%A7%BB%3A%20%E6%96%B0%E9%94%AE%E4%B8%8D%E7%AC%A6%E5%90%88%E6%97%A7%E5%88%86%E5%B8%83%22%5D%20-.-%3E%7CCDF%20%E8%BF%87%E6%9C%9F%7C%20WRONG%5B%22%E9%A2%84%E6%B5%8B%E9%A1%B5%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E7%A7%BB%2C%20%E6%90%9C%E7%B4%A2%E8%8C%83%E5%9B%B4%E6%9A%B4%E6%B6%A8%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p>这张图回答的问题：一个「模型」凭什么能当索引。有序键的排名就是其经验 CDF 乘以总数——CDF 天生是「键到位置」的函数；模型只是把这个函数拟合下来。最后一行是它的命门：拟合的是<strong>过去</strong>的分布，键一漂移预测就整体偏。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲变长溢出页。也不把学习索引用于空间 MBR（研究有，主干不依赖）。字符串键、多列组合键的模型更脆。</p><p>后课默认：学习索引适合只读或 LSM 段上的有序点查；OLTP 默认精确树。变长记录与溢出页：行存页装不下时的经典问题，与模型无关。</p><p>近似结构必须有精确收尾，否则隔离与约束都无法谈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>学习索引回归键到位置，再用局部搜索纠正。</li><li>动态更新与分布漂移是硬边界；LSM 段上更自然。</li><li>变长记录与溢出页下一课：行在页里如何拆。</li><li>出处：Kraska et al. SIGMOD 2018；B+ / ART 对照。</li></ul>',7))])}const h=o(p,[["render",D]]);export{S as __pageData,h as default};
